  if (typeof value !== 'string') return null;
  const trimmed = value.trim().replace(/^['"]|['"]$/g, '').trim();
  return trimmed || null;
};

const KEY_NAME = 'OPENAI_API_KEY';
const DEFINITION = /^(\s*(?:export\s+)?OPENAI_API_KEY\s*=\s*)(.*)$/;

// Splits the text after `=` into the value and whatever follows it (comment, spacing).
const parseEnvValue = (raw) => {
  const quote = raw[0];
  if (quote === '"' || quote === "'") {
    let i = 1;
    let value = '';
    while (i < raw.length) {
      const ch = raw[i];
      if (quote === '"' && ch === '\\' && i + 1 < raw.length) {
        value += raw[i + 1];
        i += 2;
        continue;
      }
      if (ch === quote) {
        const rest = raw.slice(i + 1);
        if (/^\s*(#.*)?$/.test(rest)) return { value, rest };
        break;
      }
      value += ch;
      i += 1;
    }
  }
  const hash = raw.search(/(^|\s)#/);
  const body = hash === -1 ? raw : raw.slice(0, hash);
  return { value: body.trim(), rest: hash === -1 ? '' : raw.slice(hash).replace(/^\s*/, ' ') };
};

const findLastDefinition = (lines) => {
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const match = lines[i].match(DEFINITION);
    if (match) return { index: i, prefix: match[1], parsed: parseEnvValue(match[2]) };
  }
  return null;
};

const splitLines = (content) => content.split(/\r?\n/);

const formatEnvValue = (key) => (/^[^\s#'"\\]+$/.test(key) ? key : JSON.stringify(key));

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  if (!fs.existsSync(envPath)) return null;
  const found = findLastDefinition(splitLines(fs.readFileSync(envPath, 'utf8')));
  if (!found) return null;
  return found.parsed.value.trim() || null;
};

export const hasLocalApiKey = (cwd = process.cwd()) => Boolean(getLocalApiKey(cwd));

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  if (!key || !key.trim()) throw new Error('API key is required');
  const envPath = resolveLocalEnvPath(cwd);
  const line = `${KEY_NAME}=${formatEnvValue(key)}`;
  if (!fs.existsSync(envPath)) {
    fs.writeFileSync(envPath, `${line}\n`, { encoding: 'utf8', mode: 0o600 });
    return envPath;
  }
  const content = fs.readFileSync(envPath, 'utf8');
  // Split keeping the original line terminators so untouched lines stay byte-for-byte.
  const parts = content.split(/(\r?\n)/);
  const lines = parts.filter((_, i) => i % 2 === 0);
  const found = findLastDefinition(lines);
  let updated;
  if (found) {
    parts[found.index * 2] = `${found.prefix}${formatEnvValue(key)}${found.parsed.rest}`;
    updated = parts.join('');
  } else {
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const sep = content === '' || /\n$/.test(content) ? '' : eol;
    updated = `${content}${sep}${line}${eol}`;
  }
  fs.writeFileSync(envPath, updated, { encoding: 'utf8' });
  return envPath;
};

